using System;
using System.Collections;
using UnityEngine;

public static class MaterialExtensions
{
	public static void SetAlpha(this Material material, float alpha)
	{
		material.SetFloat("_Alpha", alpha);
	}

	public static IEnumerator FadeSprite(this Material material, float targetAlpha, float duration, AnimationCurve curve)
	{
		float startingAlpha = material.Alpha();
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		});
	}

	public static IEnumerator FadeSprite(this Material material, float targetAlpha, float duration, AnimationCurve curve, bool isRealtime)
	{
		float startingAlpha = material.Alpha();
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		}, isRealtime);
	}

	public static IEnumerator FadeSprite(this Material material, float targetAlpha, float duration, AnimationCurve curve, Action endAction)
	{
		float startingAlpha = material.Alpha();
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		}, endAction);
	}

	public static IEnumerator FadeSprite(this Material material, float targetAlpha, float duration)
	{
		float startingAlpha = material.Alpha();
		return CoroutineUtility.CurveRoutine(duration, delegate(float t, float v)
		{
			material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		});
	}

	public static IEnumerator FadeSprite(this Material material, float targetAlpha, float duration, Action endAction)
	{
		float startingAlpha = material.Alpha();
		return CoroutineUtility.CurveRoutine(duration, delegate(float t, float v)
		{
			material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
		}, endAction);
	}

	public static IEnumerator BlinkMaterial(this Material material, float targetAlpha, float duration, int cycles)
	{
		float startingAlpha = material.Alpha();
		AnimationCurve curve = new AnimationCurve();
		curve.AddKey(0f, 0f);
		curve.AddKey(0.5f, 1f);
		curve.AddKey(1f, 0f);
		for (int i = 0; i < cycles; i++)
		{
			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
			});
		}
	}

	public static IEnumerator BlinkMaterialWithDelayToStartEffect(this Material material, float startingAlpha, float targetAlpha, float duration, int cycles, float delay = 0.2f)
	{
		yield return new WaitForSeconds(delay);
		yield return material.BlinkMaterial(startingAlpha, targetAlpha, duration, cycles);
	}

	public static IEnumerator BlinkMaterial(this Material material, float startingAlpha, float targetAlpha, float duration, int cycles)
	{
		AnimationCurve curve = new AnimationCurve();
		curve.AddKey(0f, 0f);
		curve.AddKey(0.5f, 1f);
		curve.AddKey(1f, 0f);
		for (int i = 0; i < cycles; i++)
		{
			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
			});
		}
	}

	public static IEnumerator BlinkMaterial(this Material material, float startingAlpha, float targetAlpha, float duration, int cycles, Action endAction)
	{
		AnimationCurve curve = new AnimationCurve();
		curve.AddKey(0f, 0f);
		curve.AddKey(0.5f, 1f);
		curve.AddKey(1f, 0f);
		for (int i = 0; i < cycles; i++)
		{
			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
			}, endAction);
		}
	}

	public static IEnumerator BlinkMaterial(this Material material, float startingAlpha, float targetAlpha, float duration, int cycles, bool isRealtime)
	{
		AnimationCurve curve = new AnimationCurve();
		curve.AddKey(0f, 0f);
		curve.AddKey(0.5f, 1f);
		curve.AddKey(1f, 0f);
		for (int i = 0; i < cycles; i++)
