			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
			}, isRealtime);
		}
	}

	public static IEnumerator BlinkMaterial(this Material material, float targetAlpha, float duration, int cycles, AnimationCurve curve)
	{
		float startingAlpha = material.Alpha();
		yield return material.BlinkMaterial(startingAlpha, targetAlpha, duration, cycles, curve);
	}

	public static IEnumerator BlinkMaterial(this Material material, float startingAlpha, float targetAlpha, float duration, int cycles, AnimationCurve curve)
	{
		for (int i = 0; i < cycles; i++)
		{
			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				material.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v));
			});
		}
	}

	public static IEnumerator BlinkMaterialColor(this Material material, Color startingColor, Color targetColor, float duration, int cycles, Action endAction)
	{
		AnimationCurve curve = new AnimationCurve();
		curve.AddKey(0f, 0f);
		curve.AddKey(0.5f, 1f);
		curve.AddKey(1f, 0f);
		for (int i = 0; i < cycles; i++)
		{
			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				material.SetMaterialColor(Color.Lerp(startingColor, targetColor, v));
			}, endAction);
		}
