	public static IEnumerator BlinkMaterialColor(this Material material, Color startingColor, Color targetColor, float duration, int cycles)
	{
		AnimationCurve curve = new AnimationCurve();
		curve.AddKey(0f, 0f);
		curve.AddKey(0.5f, 1f);
		curve.AddKey(1f, 0f);
		for (int i = 0; i < cycles; i++)
		{
			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				material.SetMaterialColor(Color.Lerp(startingColor, targetColor, v));
			});
		}
	}

	public static IEnumerator TweenFloatProperty(this Material material, string property, float startingValue, float targetValue, float duration, AnimationCurve curve)
	{
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			material.SetFloat(property, Mathf.Lerp(startingValue, targetValue, v));
		});
	}

	public static IEnumerator TweenFloatProperty(this Material material, string property, float targetValue, float duration, AnimationCurve curve)
	{
		float startingValue = material.GetFloat(property);
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			material.SetFloat(property, Mathf.Lerp(startingValue, targetValue, v));
		});
	}

	public static IEnumerator TweenFloatProperty(this Material material, string property, float targetValue, float duration)
	{
		return material.TweenFloatProperty(property, targetValue, duration, CoroutineUtility.LinearCurve());
	}

	public static void SetMaterialColor(this Material material, Color color)
	{
		material.SetColor("_Color", color);
	}

	public static Color GetMaterialColor(this Material material)
	{
		return material.GetColor("_Color");
	}

	public static float Alpha(this Material material)
	{
		return material.GetFloat("_Alpha");
	}
}
